import math

def euclidean(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def knn_predict(X_train, y_train, point, k=3):
    dists = sorted([(euclidean(x, point), label) for x, label in zip(X_train, y_train)])
    neighbors = [label for _, label in dists[:k]]
    return max(set(neighbors), key=neighbors.count)

X_train = [[1,1],[1,2],[2,1],[5,5],[5,6],[6,5]]
y_train = ['A','A','A','B','B','B']

for point in [[2,2],[5,4]]:
    print(f"{point} -> {knn_predict(X_train, y_train, point)}")
